<template><div><h1 class="page-title">问答分析</h1><p class="page-desc">统计高频问题、无引用问题和低质量问题，辅助教师优化课程资料。</p><div v-if="!auth.hasCourse" class="empty-state">请先选择课程。</div><template v-else><el-card class="panel-card"><el-button type="primary" :loading="loading" @click="loadAll">刷新分析数据</el-button></el-card><el-card v-for="block in blocks" :key="block.title" class="panel-card"><h2>{{ block.title }}</h2><div v-if="!block.items.length" class="empty-state">暂无数据</div><el-table v-else :data="block.items" stripe style="width:100%"/></el-card><el-card class="panel-card"><h2>处理低质量问题</h2><div v-if="!lowQuality.length" class="empty-state">请先点击“刷新分析数据”，并确保课程中存在低质量问题记录。</div><el-form v-else :model="processForm" label-position="top"><el-form-item label="选择问答事件"><el-select v-model="processForm.event_id" filterable><el-option v-for="it in lowQuality" :key="it.event_id" :label="`${it.event_id}｜${String(it.question||'').slice(0,60)}`" :value="it.event_id"/></el-select></el-form-item><el-form-item label="处理状态"><el-select v-model="processForm.status"><el-option v-for="s in statuses" :key="s" :label="s" :value="s"/></el-select></el-form-item><el-form-item label="处理备注"><el-input v-model="processForm.note" type="textarea"/></el-form-item><el-button type="primary" @click="updateStatus">更新处理状态</el-button></el-form></el-card></template></div></template>
<script setup>
import { reactive, ref } from 'vue'; import { ElMessage } from 'element-plus'; import { courseApi } from '../api'; import { errorMessage } from '../api/request'; import { useAuthStore } from '../stores/auth'
const auth=useAuthStore(); const loading=ref(false); const blocks=ref([{title:'高频问题',items:[]},{title:'无引用问题',items:[]},{title:'低质量问题',items:[]}]); const lowQuality=ref([]); const statuses=['pending','processing','resolved','ignored']; const processForm=reactive({event_id:'',status:'pending',note:''})
async function loadAll(){ loading.value=true; try{ const [a,b,c]=await Promise.all([courseApi.topQuestions(auth.currentCourseId),courseApi.noCitation(auth.currentCourseId),courseApi.lowQuality(auth.currentCourseId)]); blocks.value=[{title:'高频问题',items:a.data.items||[]},{title:'无引用问题',items:b.data.items||[]},{title:'低质量问题',items:c.data.items||[]}]; lowQuality.value=c.data.items||[] }catch(e){ ElMessage.error(errorMessage(e)) }finally{ loading.value=false } }
async function updateStatus(){ if(!processForm.event_id) return ElMessage.error('请选择要处理的问答事件'); try{ await courseApi.updateQaEventStatus(auth.currentCourseId,processForm.event_id,{status:processForm.status,note:processForm.note}); ElMessage.success('处理状态已更新') }catch(e){ ElMessage.error(errorMessage(e)) } }
</script>
<style scoped>.panel-card{margin-bottom:18px}.panel-card h2{margin-top:0;color:#0f172a}</style>
